'use strict';

// Seeds the Kalender Islam dataset (data/falak-abi-calendar.json) into the
// hijri-month-start and calendar-event content types.
//
// The JSON is generated by the mobile-app repo:
//   ensiklopedia-doa/scripts/falak-abi/generate.js  ->  cms-export.json
// Copy that file here as data/falak-abi-calendar.json when coverage extends.
//
// Idempotent: existing rows (same gregorianDate, or same date+title) are
// skipped, so re-running after adding a new year only inserts the new rows.
// Month starts are inserted in date order so the continuity lifecycle
// validation always sees the preceding month.
//
// Run with: npm run import:calendar   (uses the same DATABASE_* env as the
// server, so run it locally for the dev DB or with production env vars —
// e.g. `railway run npm run import:calendar` — for the deployed CMS.)

const data = require('../data/falak-abi-calendar.json');

const MONTH_START_UID = 'api::hijri-month-start.hijri-month-start';
const EVENT_UID = 'api::calendar-event.calendar-event';

const HIJRI_MONTH_NAMES = [
  'Muharam',
  'Safar',
  'Rabiulawal',
  'Rabiulakhir',
  'Jumadilawal',
  'Jumadilakhir',
  'Rajab',
  'Syakban',
  'Ramadan',
  'Syawal',
  'Zulqaidah',
  'Zulhijah',
];

async function importMonthStarts(app) {
  let created = 0;
  let skipped = 0;
  const sorted = [...data.monthStarts].sort((a, b) => a.g.localeCompare(b.g));
  for (const start of sorted) {
    const existing = await app.documents(MONTH_START_UID).findFirst({
      filters: { gregorianDate: start.g },
    });
    if (existing) {
      skipped++;
      continue;
    }
    await app.documents(MONTH_START_UID).create({
      data: {
        gregorianDate: start.g,
        hijriMonth: HIJRI_MONTH_NAMES[start.hm],
        hijriYear: start.hy,
        sourceNote: 'Import kalender 2025-2030',
      },
    });
    created++;
  }
  console.log(`Month starts: ${created} created, ${skipped} skipped (already present)`);
}

async function importEvents(app) {
  let created = 0;
  let skipped = 0;
  for (const event of data.events) {
    const existing = await app.documents(EVENT_UID).findFirst({
      filters: { date: event.date, title: event.text },
    });
    if (existing) {
      skipped++;
      continue;
    }
    await app.documents(EVENT_UID).create({
      data: {
        date: event.date,
        title: event.text,
        kind: event.kind === 'event' ? 'hari_besar' : 'astronomi',
      },
      status: 'published',
    });
    created++;
  }
  console.log(`Events: ${created} created, ${skipped} skipped (already present)`);
}

async function main() {
  const { createStrapi, compileStrapi } = require('@strapi/strapi');
  const appContext = await compileStrapi();
  const app = await createStrapi(appContext).load();
  app.log.level = 'error';
  try {
    console.log(
      `Importing ${data.monthStarts.length} month starts and ${data.events.length} events...`,
    );
    await importMonthStarts(app);
    await importEvents(app);
  } finally {
    await app.destroy();
  }
}

main().catch((error) => {
  console.error('Import failed:', error);
  process.exit(1);
});
